import{c as e}from"./app.8a64fc3d.js";import{_ as a}from"./plugin-vue_export-helper.21dcd24c.js";const i={},r=e('<h3 id="_1-savage-\u02C8s\xE6v\u026Ad\u0292-\u51F6\u731B\u7684-\u6FC0\u70C8\u7684-\u53E3\u8BED-\u72E0\u7684\u3001\u7280\u5229\u7684" tabindex="-1"><a class="header-anchor" href="#_1-savage-\u02C8s\xE6v\u026Ad\u0292-\u51F6\u731B\u7684-\u6FC0\u70C8\u7684-\u53E3\u8BED-\u72E0\u7684\u3001\u7280\u5229\u7684" aria-hidden="true">#</a> 1.savage /\u02C8s\xE6v\u026Ad\u0292/ \u51F6\u731B\u7684\uFF1B\u6FC0\u70C8\u7684\uFF1B\uFF08\u53E3\u8BED\uFF09\u72E0\u7684\u3001\u7280\u5229\u7684</h3><ol><li>The storm was savage and destroyed many houses.\uFF08\u66B4\u98CE\u96E8\u975E\u5E38\u731B\u70C8\uFF0C\u6BC1\u574F\u4E86\u5F88\u591A\u623F\u5B50\u3002\uFF09</li><li>Her comment was savage but honest.\uFF08\u5979\u7684\u8BC4\u4EF7\u5F88\u7280\u5229\uFF0C\u4F46\u5F88\u771F\u5B9E\u3002\uFF09</li></ol><h3 id="_2-solely-\u02C8s\u0259\u028Al-li-\u02C8so\u028Al-\u4EC5\u4EC5-\u5B8C\u5168\u5730" tabindex="-1"><a class="header-anchor" href="#_2-solely-\u02C8s\u0259\u028Al-li-\u02C8so\u028Al-\u4EC5\u4EC5-\u5B8C\u5168\u5730" aria-hidden="true">#</a> 2.solely /\u02C8s\u0259\u028Al-li $ \u02C8so\u028Al-/ \u4EC5\u4EC5\uFF1B\u5B8C\u5168\u5730</h3><ol><li>The decision was based solely on experience.\uFF08\u8FD9\u4E2A\u51B3\u5B9A\u5B8C\u5168\u662F\u57FA\u4E8E\u7ECF\u9A8C\u3002\uFF09</li><li>He relies solely on his legs when swimming.\uFF08\u4ED6\u6E38\u6CF3\u65F6\u5B8C\u5168\u4F9D\u9760\u53CC\u817F\u3002\uFF09</li></ol><h3 id="_3-drill-dr\u026Al-\u8BAD\u7EC3\u52A8\u4F5C-\u4E13\u9879\u7EC3\u4E60" tabindex="-1"><a class="header-anchor" href="#_3-drill-dr\u026Al-\u8BAD\u7EC3\u52A8\u4F5C-\u4E13\u9879\u7EC3\u4E60" aria-hidden="true">#</a> 3.drill /dr\u026Al/ \u8BAD\u7EC3\u52A8\u4F5C\uFF0C\u4E13\u9879\u7EC3\u4E60</h3><ol><li>Our coach gave us several swimming drills.\uFF08\u6559\u7EC3\u7ED9\u6211\u4EEC\u5B89\u6392\u4E86\u51E0\u4E2A\u6E38\u6CF3\u4E13\u9879\u7EC3\u4E60\u3002\uFF09</li><li>Repeating the same drill helps improve technique.\uFF08\u53CD\u590D\u505A\u540C\u4E00\u4E2A\u8BAD\u7EC3\u52A8\u4F5C\u6709\u52A9\u4E8E\u63D0\u9AD8\u6280\u672F\u3002\uFF09</li></ol><h3 id="_4-foam-f\u0259\u028Am-fo\u028Am-\u6CE1\u6CAB-\u6CE1\u6CAB\u6750\u6599" tabindex="-1"><a class="header-anchor" href="#_4-foam-f\u0259\u028Am-fo\u028Am-\u6CE1\u6CAB-\u6CE1\u6CAB\u6750\u6599" aria-hidden="true">#</a> 4.foam /f\u0259\u028Am $ fo\u028Am/ \u6CE1\u6CAB\uFF0C\u6CE1\u6CAB\u6750\u6599</h3><ol><li>The swimming pool provides foam boards for beginners.\uFF08\u6E38\u6CF3\u6C60\u4E3A\u521D\u5B66\u8005\u63D0\u4F9B\u6CE1\u6CAB\u6D6E\u677F\u3002\uFF09</li><li>He put a foam pillow under his head.\uFF08\u4ED6\u628A\u4E00\u4E2A\u6CE1\u6CAB\u6795\u5934\u57AB\u5728\u5934\u4E0B\u3002\uFF09</li></ol><h3 id="_5-wiggle-\u02C8w\u026A\u0261\u0259l-\u626D\u52A8-\u6446\u52A8-\u5C0F\u5E45\u5EA6" tabindex="-1"><a class="header-anchor" href="#_5-wiggle-\u02C8w\u026A\u0261\u0259l-\u626D\u52A8-\u6446\u52A8-\u5C0F\u5E45\u5EA6" aria-hidden="true">#</a> 5.wiggle /\u02C8w\u026A\u0261\u0259l/ \u626D\u52A8\uFF0C\u6446\u52A8\uFF08\u5C0F\u5E45\u5EA6\uFF09</h3><ol><li>The baby wiggled his toes.\uFF08\u5B9D\u5B9D\u626D\u52A8\u7740\u811A\u8DBE\u3002\uFF09</li><li>She wiggled through the narrow gap.\uFF08\u5979\u626D\u7740\u8EAB\u4F53\u7A7F\u8FC7\u4E86\u72ED\u7A84\u7684\u7F1D\u9699\u3002\uFF09</li></ol><h3 id="_6-wobble-\u02C8w\u0252b\u0259l-\u02C8w\u0251\u02D0-\u6447\u6643-\u6447\u6446-\u7AD9\u4E0D\u7A33-\u6446\u52A8-\u5927\u5E45\u5EA6" tabindex="-1"><a class="header-anchor" href="#_6-wobble-\u02C8w\u0252b\u0259l-\u02C8w\u0251\u02D0-\u6447\u6643-\u6447\u6446-\u7AD9\u4E0D\u7A33-\u6446\u52A8-\u5927\u5E45\u5EA6" aria-hidden="true">#</a> 6.wobble /\u02C8w\u0252b\u0259l $ \u02C8w\u0251\u02D0-/ \u6447\u6643\uFF0C\u6447\u6446\uFF0C\u7AD9\u4E0D\u7A33\uFF0C\u6446\u52A8\uFF08\u5927\u5E45\u5EA6\uFF09</h3><ol><li>The table wobbles because one leg is shorter.\uFF08\u684C\u5B50\u56E0\u4E3A\u4E00\u6761\u817F\u8F83\u77ED\u800C\u6447\u6643\u3002\uFF09</li><li>I wobbled a little when I got off the boat.\uFF08\u6211\u4E0B\u8239\u65F6\u6709\u70B9\u7AD9\u4E0D\u7A33\u3002\uFF09</li></ol><h3 id="_7-pamphlet-\u02C8p\xE6mfl\u0259t-\u5C0F\u518C\u5B50-\u5E38\u5305\u542B\u6709\u5173\u67D0\u4E00\u4E3B\u9898\u7684\u4FE1\u606F\u3001\u5BA3\u4F20\u8D44\u6599\u7B49" tabindex="-1"><a class="header-anchor" href="#_7-pamphlet-\u02C8p\xE6mfl\u0259t-\u5C0F\u518C\u5B50-\u5E38\u5305\u542B\u6709\u5173\u67D0\u4E00\u4E3B\u9898\u7684\u4FE1\u606F\u3001\u5BA3\u4F20\u8D44\u6599\u7B49" aria-hidden="true">#</a> 7.pamphlet /\u02C8p\xE6mfl\u0259t/ \u5C0F\u518C\u5B50\uFF08\u5E38\u5305\u542B\u6709\u5173\u67D0\u4E00\u4E3B\u9898\u7684\u4FE1\u606F\u3001\u5BA3\u4F20\u8D44\u6599\u7B49\uFF09</h3><ol><li>They handed out pamphlets about environmental protection.\uFF08\u4ED6\u4EEC\u5206\u53D1\u5173\u4E8E\u73AF\u5883\u4FDD\u62A4\u7684\u5C0F\u518C\u5B50\u3002\uFF09</li><li>I read a pamphlet about the new product.\uFF08\u6211\u8BFB\u4E86\u4E00\u672C\u5173\u4E8E\u65B0\u4EA7\u54C1\u7684\u5C0F\u518C\u5B50\u3002\uFF09</li></ol><h3 id="_8-squeeze-skwi\u02D0z-\u538B\u7F29-\u6324\u538B" tabindex="-1"><a class="header-anchor" href="#_8-squeeze-skwi\u02D0z-\u538B\u7F29-\u6324\u538B" aria-hidden="true">#</a> 8.squeeze /skwi\u02D0z/ \u538B\u7F29\uFF0C\u6324\u538B</h3><ol><li>I&#39;ll try to squeeze in a workout before dinner.\uFF08\u6211\u4F1A\u5C3D\u91CF\u5728\u665A\u996D\u524D\u6324\u51FA\u65F6\u95F4\u953B\u70BC\u4E00\u4E0B\u3002\uFF09</li><li>Can you squeeze in a meeting with me this afternoon?\uFF08\u4F60\u4ECA\u5929\u4E0B\u5348\u80FD\u6324\u51FA\u65F6\u95F4\u548C\u6211\u5F00\u4E2A\u4F1A\u5417\uFF1F\uFF09</li></ol><h3 id="_9-motion-sickness-\u02C8m\u0259\u028A\u0283\u0259n-\u02C8mo\u028A-\u6655\u52A8\u75C5-\u8F66\u75C5" tabindex="-1"><a class="header-anchor" href="#_9-motion-sickness-\u02C8m\u0259\u028A\u0283\u0259n-\u02C8mo\u028A-\u6655\u52A8\u75C5-\u8F66\u75C5" aria-hidden="true">#</a> 9.motion sickness /\u02C8m\u0259\u028A\u0283\u0259n $ \u02C8mo\u028A-/ \u6655\u52A8\u75C5\uFF0C\u8F66\u75C5</h3><ol><li>She always gets motion sickness when she travels by car.\uFF08\u5979\u6BCF\u6B21\u5750\u8F66\u90FD\u4F1A\u6655\u8F66\u3002\uFF09</li><li>Taking some medicine can help relieve motion sickness.\uFF08\u5403\u4E9B\u836F\u53EF\u4EE5\u5E2E\u52A9\u7F13\u89E3\u6655\u52A8\u75C5\u3002\uFF09</li></ol><h3 id="_10-layover-\u02C8le\u026A\u0259\u028Av\u0259-o\u028Av\u0259r-\u8F6C\u673A\u505C\u7559" tabindex="-1"><a class="header-anchor" href="#_10-layover-\u02C8le\u026A\u0259\u028Av\u0259-o\u028Av\u0259r-\u8F6C\u673A\u505C\u7559" aria-hidden="true">#</a> 10.layover /\u02C8le\u026A\u0259\u028Av\u0259 $ -o\u028Av\u0259r/ \u8F6C\u673A\u505C\u7559</h3><ol><li>We had a four-hour layover in Dubai before catching our next flight.\uFF08\u6211\u4EEC\u5728\u8FEA\u62DC\u8F6C\u673A\u505C\u7559\u4E86\u56DB\u4E2A\u5C0F\u65F6\uFF0C\u7136\u540E\u624D\u8D76\u4E0A\u4E0B\u4E00\u73ED\u98DE\u673A\u3002\uFF09</li><li>During the layover, I explored the airport and grabbed a quick meal.\uFF08\u5728\u8F6C\u673A\u505C\u7559\u671F\u95F4\uFF0C\u6211\u5728\u673A\u573A\u901B\u4E86\u901B\uFF0C\u8FD8\u968F\u4FBF\u5403\u4E86\u70B9\u4E1C\u897F\u3002\uFF09</li></ol><h3 id="_11-be-cocooned-in-sth-k\u0259\u02C8ku\u02D0n-\u88AB-\u5305\u88F9\u7740-\u88AB-\u6E29\u67D4\u5730\u56F4\u7ED5\u7740" tabindex="-1"><a class="header-anchor" href="#_11-be-cocooned-in-sth-k\u0259\u02C8ku\u02D0n-\u88AB-\u5305\u88F9\u7740-\u88AB-\u6E29\u67D4\u5730\u56F4\u7ED5\u7740" aria-hidden="true">#</a> 11.be cocooned in sth. /k\u0259\u02C8ku\u02D0n/ \u88AB\u2026\u2026\u5305\u88F9\u7740\uFF1B\u88AB\u2026\u2026\u6E29\u67D4\u5730\u56F4\u7ED5\u7740</h3><ol><li>I felt cocooned in the warm blanket.\uFF08\u6211\u611F\u89C9\u81EA\u5DF1\u88AB\u6E29\u6696\u7684\u6BEF\u5B50\u5305\u88F9\u7740\u3002\uFF09</li><li>She was cocooned in silence as she read her book.\uFF08\u5979\u8BFB\u4E66\u65F6\u4EFF\u4F5B\u88AB\u5B81\u9759\u5305\u56F4\u7740\u3002\uFF09</li></ol><h3 id="_12-hilarious-h\u026A\u02C8le\u0259ri\u0259s-\u02C8ler-\u975E\u5E38\u597D\u7B11\u7684-\u6ED1\u7A3D\u7684" tabindex="-1"><a class="header-anchor" href="#_12-hilarious-h\u026A\u02C8le\u0259ri\u0259s-\u02C8ler-\u975E\u5E38\u597D\u7B11\u7684-\u6ED1\u7A3D\u7684" aria-hidden="true">#</a> 12.hilarious /h\u026A\u02C8le\u0259ri\u0259s $ -\u02C8ler-/ \u975E\u5E38\u597D\u7B11\u7684\uFF1B\u6ED1\u7A3D\u7684</h3><ol><li>That movie was absolutely hilarious!\uFF08\u90A3\u90E8\u7535\u5F71\u771F\u662F\u592A\u641E\u7B11\u4E86\uFF01\uFF09</li><li>She told a hilarious story about her first day at work.\uFF08\u5979\u8BB2\u4E86\u4E00\u4E2A\u5173\u4E8E\u5979\u4E0A\u73ED\u7B2C\u4E00\u5929\u7684\u8D85\u7EA7\u641E\u7B11\u7684\u6545\u4E8B\u3002\uFF09</li></ol><h3 id="_13-resonate-with-sth-\u02C8rez\u0259ne\u026At-\u4E0E-\u4EA7\u751F\u5171\u9E23-\u5BF9-\u6709\u5171\u9E23" tabindex="-1"><a class="header-anchor" href="#_13-resonate-with-sth-\u02C8rez\u0259ne\u026At-\u4E0E-\u4EA7\u751F\u5171\u9E23-\u5BF9-\u6709\u5171\u9E23" aria-hidden="true">#</a> 13.resonate with sth /\u02C8rez\u0259ne\u026At/ \u4E0E\u2026\u2026\u4EA7\u751F\u5171\u9E23\uFF1B\u5BF9\u2026\u2026\u6709\u5171\u9E23</h3><ol><li>Her speech really resonated with the audience.\uFF08\u5979\u7684\u6F14\u8BB2\u8BA9\u542C\u4F17\u6DF1\u53D7\u5171\u9E23\u3002\uFF09</li><li>That idea doesn\u2019t really resonate with me.\uFF08\u90A3\u4E2A\u60F3\u6CD5\u5E76\u4E0D\u80FD\u771F\u6B63\u5F15\u8D77\u6211\u7684\u5171\u9E23\u3002\uFF09</li></ol><h3 id="_14-tropic-\u02C8tr\u0252p\u026Ak-\u02C8tr\u0251\u02D0-\u70ED\u5E26\u7684-\u70ED\u5E26\u7684" tabindex="-1"><a class="header-anchor" href="#_14-tropic-\u02C8tr\u0252p\u026Ak-\u02C8tr\u0251\u02D0-\u70ED\u5E26\u7684-\u70ED\u5E26\u7684" aria-hidden="true">#</a> 14.tropic /\u02C8tr\u0252p\u026Ak $ \u02C8tr\u0251\u02D0-/ \u70ED\u5E26\u7684\uFF1B\u70ED\u5E26\u7684</h3><ol><li>Many people dream of living in the tropics.\uFF08\u5F88\u591A\u4EBA\u68A6\u60F3\u751F\u6D3B\u5728\u70ED\u5E26\u5730\u533A\u3002\uFF09</li><li>The tropics are known for their warm climate and lush vegetation.\uFF08\u70ED\u5E26\u5730\u533A\u4EE5\u6E29\u6696\u7684\u6C14\u5019\u548C\u8302\u5BC6\u7684\u690D\u88AB\u800C\u95FB\u540D\u3002\uFF09</li></ol><h3 id="_15-vibrant-\u02C8va\u026Abr\u0259nt-\u5145\u6EE1\u6D3B\u529B\u7684-\u8272\u5F69\u9C9C\u8273\u7684" tabindex="-1"><a class="header-anchor" href="#_15-vibrant-\u02C8va\u026Abr\u0259nt-\u5145\u6EE1\u6D3B\u529B\u7684-\u8272\u5F69\u9C9C\u8273\u7684" aria-hidden="true">#</a> 15.vibrant /\u02C8va\u026Abr\u0259nt/ \u5145\u6EE1\u6D3B\u529B\u7684\uFF1B\u8272\u5F69\u9C9C\u8273\u7684</h3><ol><li>The market was vibrant and full of energy.\uFF08\u5E02\u573A\u5145\u6EE1\u6D3B\u529B\uFF0C\u70ED\u95F9\u975E\u51E1\u3002\uFF09</li><li>She loves the vibrant colors of the rainforest.\uFF08\u5979\u5F88\u559C\u6B22\u96E8\u6797\u4E2D\u9C9C\u8273\u7684\u8272\u5F69\u3002\uFF09</li></ol><h3 id="_16-towering-\u02C8ta\u028A\u0259r\u026A\u014B-\u9AD8\u8038\u7684" tabindex="-1"><a class="header-anchor" href="#_16-towering-\u02C8ta\u028A\u0259r\u026A\u014B-\u9AD8\u8038\u7684" aria-hidden="true">#</a> 16.towering /\u02C8ta\u028A\u0259r\u026A\u014B/ \u9AD8\u8038\u7684</h3><ol><li>Towering trees surrounded the river.\uFF08\u9AD8\u8038\u7684\u6811\u6728\u73AF\u7ED5\u7740\u6CB3\u6D41\u3002\uFF09</li><li>The city is famous for its towering skyscrapers.\uFF08\u8FD9\u5EA7\u57CE\u5E02\u4EE5\u9AD8\u8038\u7684\u6469\u5929\u5927\u697C\u800C\u95FB\u540D\u3002\uFF09</li></ol><h3 id="_17-rodent-\u02C8r\u0259\u028Ad\u0259nt-\u02C8ro\u028A-\u556E\u9F7F\u52A8\u7269" tabindex="-1"><a class="header-anchor" href="#_17-rodent-\u02C8r\u0259\u028Ad\u0259nt-\u02C8ro\u028A-\u556E\u9F7F\u52A8\u7269" aria-hidden="true">#</a> 17.rodent /\u02C8r\u0259\u028Ad\u0259nt $ \u02C8ro\u028A-/ \u556E\u9F7F\u52A8\u7269</h3><ol><li>Mice and squirrels are common rodents.\uFF08\u8001\u9F20\u548C\u677E\u9F20\u662F\u5E38\u89C1\u7684\u556E\u9F7F\u52A8\u7269\u3002\uFF09</li><li>The capybara is a large rodent.\uFF08\u6C34\u8C5A\u662F\u4E00\u79CD\u5927\u578B\u556E\u9F7F\u52A8\u7269\u3002\uFF09</li></ol><h3 id="_18-instant-\u02C8\u026Anst\u0259nt-adj-\u77AC\u95F4\u7684-\u7ACB\u5373\u7684-n-\u77AC\u95F4-\u5239\u90A3" tabindex="-1"><a class="header-anchor" href="#_18-instant-\u02C8\u026Anst\u0259nt-adj-\u77AC\u95F4\u7684-\u7ACB\u5373\u7684-n-\u77AC\u95F4-\u5239\u90A3" aria-hidden="true">#</a> 18.instant /\u02C8\u026Anst\u0259nt/ adj. \u77AC\u95F4\u7684\uFF0C\u7ACB\u5373\u7684\uFF1Bn. \u77AC\u95F4\uFF0C\u5239\u90A3</h3><ol><li>The news spread in an instant.\uFF08\u8FD9\u6761\u6D88\u606F\u77AC\u95F4\u5C31\u4F20\u5F00\u4E86\u3002\uFF09</li><li>He got an instant response from the customer service team.\uFF08\u4ED6\u7ACB\u5373\u6536\u5230\u4E86\u5BA2\u670D\u56E2\u961F\u7684\u56DE\u590D\u3002\uFF09</li></ol><h3 id="_19-leash-li\u02D0\u0283-\u72D7\u7EF3-\u7275\u5F15\u7EF3" tabindex="-1"><a class="header-anchor" href="#_19-leash-li\u02D0\u0283-\u72D7\u7EF3-\u7275\u5F15\u7EF3" aria-hidden="true">#</a> 19.leash /li\u02D0\u0283/ \u72D7\u7EF3\uFF0C\u7275\u5F15\u7EF3</h3><ol><li>Please keep your dog on a leash in the park.\uFF08\u8BF7\u5728\u516C\u56ED\u91CC\u7528\u72D7\u7EF3\u7275\u7740\u72D7\u3002\uFF09</li><li>He held the leash tightly when the dog started to run.\uFF08\u5F53\u72D7\u5F00\u59CB\u8DD1\u65F6\uFF0C\u4ED6\u7D27\u7D27\u5730\u62FD\u4F4F\u72D7\u7EF3\u3002\uFF09</li></ol>',38);function l(o,t){return r}var s=a(i,[["render",l]]);export{s as default};
